/**
 * Detects "internal" traffic that is not a bot per se, but is
 * generated by development/deployment processes and should be
 * excluded from business analytics.
 *
 * Categories:
 * 1. Vercel preview deployment referrers
 * 2. localhost / 127.0.0.1 referrers
 * 3. Known development tool referrers
 */

/** Production domains that should NOT be flagged as internal */
const PRODUCTION_DOMAINS = [
  'deepdivecareer.com',
  'www.deepdivecareer.com',
  'v0-career-exploration-questionnaire.vercel.app',
];

/**
 * Patterns that indicate the traffic is from internal/dev sources.
 * Checked against the referer header.
 */
const INTERNAL_REFERER_PATTERNS: RegExp[] = [
  // Vercel preview deploys — hash-based URLs
  /v0-career-exploration-questionnaire-[a-z0-9]+\.vercel\.app/i,
  // Generic Vercel preview pattern
  /\.vercel\.app$/i,
  // Localhost development
  /localhost/i,
  /127\.0\.0\.1/i,
  /\[::1\]/i,
  // Common development tools
  /\.ngrok\./i,
  /\.tunnel\./i,
];

/**
 * Patterns checked against User-Agent that suggest internal/automated traffic
 * but may not be traditional "bots". These are development and CI tools.
 */
const INTERNAL_UA_PATTERNS: RegExp[] = [
  /vercel-screenshot/i,
  /vercel-favicon/i,
  /vercel-og/i,
  // Claude Code / Anthropic automated browsing
  /Claude-Code/i,
  /claude-code/i,
  /Anthropic-AI/i,
  /anthropic-code/i,
];

export interface InternalTrafficResult {
  isInternal: boolean;
  reason: string | null;
}

/**
 * Determines if a visit is "internal" (development/deployment noise)
 * rather than a real user visit.
 */
export function detectInternalTraffic(opts: {
  referer: string | null;
  userAgent: string | null;
}): InternalTrafficResult {
  const { referer, userAgent } = opts;

  // Check User-Agent for internal patterns
  if (userAgent) {
    for (const pattern of INTERNAL_UA_PATTERNS) {
      if (pattern.test(userAgent)) {
        return { isInternal: true, reason: 'Vercel internal service' };
      }
    }
  }

  // Check referer
  if (referer) {
    // First, check if it's a known production domain — those are NOT internal
    try {
      const hostname = new URL(referer).hostname;
      if (PRODUCTION_DOMAINS.some(d => hostname === d || hostname.endsWith('.' + d))) {
        return { isInternal: false, reason: null };
      }
    } catch {
      // If URL parsing fails, continue with pattern matching
    }

    for (const pattern of INTERNAL_REFERER_PATTERNS) {
      if (pattern.test(referer)) {
        return { isInternal: true, reason: 'Preview/development referrer' };
      }
    }
  }

  return { isInternal: false, reason: null };
}
